	genl = nl_open(NETLINK_GENERIC);
	rtnl = nl_open(NETLINK_ROUTE);
	if (pipe(ready) || pipe(go))
		die_errno("pipe");

	child = fork();
	if (child < 0)
		die_errno("fork");
	if (child == 0) {
		close(ready[0]);
		close(go[1]);
		close(genl);
		close(rtnl);
		setup_victim(anchor_fd, ready[1], go[0]);
