	close(ready[1]);
	close(go[0]);
	if (read(ready[0], &byte, 1) != 1)
		die_errno("ready");
	while (!if_nametoindex(PORT_NAME))
		usleep(1000);
	set_up(rtnl, PORT_NAME);
	flood_and_release(go[1]);
	waitpid(child, NULL, 0);
	close(go[1]);
	close(ready[0]);
	close(genl);
	close(rtnl);
	close(anchor_fd);
	return 0;
}

