 	if (ret)
 		goto exit;
 
+	/* The table describes its own length; it must fit what was read */
+	if (le32_to_cpu(host_tbl->ext_host_tbl_length) < sizeof(*host_tbl) ||
+	    le32_to_cpu(host_tbl->ext_host_tbl_length) > ext_host_tbl_len) {
+		ret = -EINVAL;
+		goto exit;
+	}
+
