 	return ret;
@@ -570,34 +577,44 @@ int mm81x_fw_parse_ext_host_tbl(struct mm81x *mors)
 	end = ((u8 *)ext_host_table) +
 	      le32_to_cpu(ext_host_table->ext_host_tbl_length);
 
-	while (head < end) {
